export const GITHUB_REPOS: readonly string[] = ["owner/repo"];

export function githubRepos(): readonly string[] {
  const fromEnv = process.env.PR_AUTOFIXER_REPOS?.trim();
  const repos =
    fromEnv === undefined || fromEnv === ""
      ? [...GITHUB_REPOS]
      : fromEnv
          .split(",")
          .map((repo) => repo.trim())
          .filter((repo) => repo !== "");
  if (repos.length === 0) {
    throw new Error(
      "Set GITHUB_REPOS in bot/lib/repos.ts or PR_AUTOFIXER_REPOS to a comma-separated owner/repo list.",
    );
  }
  return repos;
}
